// Durable Object as real-time sync hub
// https://developers.cloudflare.com/durable-objects/best-practices/websockets/

import { DurableObject } from 'cloudflare:workers'

interface SyncMessage {
  type: 'update' | 'presence' | 'cursor'
  version: number
  payload: unknown
  clientId: string
  idempotencyKey: string
}

const SyncMessageSchema = z.object({
  type: z.enum(['update', 'presence', 'cursor']),
  version: z.number(),
  payload: z.unknown(),
  clientId: z.string(),
  idempotencyKey: z.string(),
})

export class SyncRoom extends DurableObject {
  private sessions = new Map<WebSocket, { clientId: string }>()
  private processedKeys = new Set<string>()  // Idempotency

  async fetch(request: Request) {
    if (request.headers.get('Upgrade') !== 'websocket') {
      return new Response('Expected WebSocket', { status: 426 })
    }

    const pair = new WebSocketPair()
    const [client, server] = Object.values(pair)

    this.ctx.acceptWebSocket(server)

    return new Response(null, { status: 101, webSocket: client })
  }

  async webSocketMessage(ws: WebSocket, raw: string | ArrayBuffer) {
    // Schema validation at boundary
    const parsed = SyncMessageSchema.safeParse(JSON.parse(raw as string))
    if (!parsed.success) {
      ws.send(JSON.stringify({ type: 'error', errors: parsed.error.issues }))
      return
    }

    const msg = parsed.data

    // Idempotency check (at-least-once from reconnects)
    if (this.processedKeys.has(msg.idempotencyKey)) return
    this.processedKeys.add(msg.idempotencyKey)

    // Persist to DO transactional storage
    if (msg.type === 'update') {
      await this.ctx.storage.sql.exec(
        `INSERT INTO sync_log (key, client_id, payload, version, created_at)
         VALUES (?, ?, ?, ?, ?)
         ON CONFLICT(key) DO UPDATE SET payload=excluded.payload, version=excluded.version`,
        [msg.idempotencyKey, msg.clientId, JSON.stringify(msg.payload), msg.version, Date.now()]
      )
    }

    // Broadcast to other clients (not sender)
    for (const [socket, session] of this.sessions) {
      if (socket !== ws && socket.readyState === WebSocket.OPEN) {
        socket.send(JSON.stringify(msg))
      }
    }
  }

  async webSocketClose(ws: WebSocket) {
    this.sessions.delete(ws)
    // Broadcast presence departure
  }
}

// Queue-based webhook sync with validation and DLQ
// https://developers.cloudflare.com/queues/

interface Env {
  WEBHOOK_QUEUE: Queue
  WEBHOOK_DLQ: Queue
  DB: D1Database
}

// Producer: receive webhook, validate signature, enqueue
export default {
  async fetch(request: Request, env: Env) {
    if (!verifyWebhookSignature(request)) {
      return new Response('Unauthorized', { status: 401 })
    }

    const idempotencyKey = request.headers.get('x-idempotency-key')
    if (!idempotencyKey) {
      return new Response('Missing idempotency key', { status: 400 })
    }

    await env.WEBHOOK_QUEUE.send({
      idempotencyKey,
      payload: await request.json(),
      receivedAt: new Date().toISOString(),
    })

    return new Response('Accepted', { status: 202 })
  },

  // Consumer: process from queue with validation
  async queue(batch: MessageBatch, env: Env) {
    for (const msg of batch.messages) {
      try {
        const result = WebhookPayloadSchema.safeParse(msg.body.payload)
        if (!result.success) {
          // Poison message -> DLQ
          await env.WEBHOOK_DLQ.send({
            original: msg.body,
            errors: result.error.issues,
            failedAt: new Date().toISOString(),
          })
          msg.ack()
          continue
        }

        // Idempotency check
        const existing = await env.DB.prepare(
          'SELECT 1 FROM sync_log WHERE idempotency_key = ?'
        ).bind(msg.body.idempotencyKey).first()

        if (existing) { msg.ack(); continue }

        // Process
        await processWebhookSync(env.DB, result.data)

        // Record idempotency
        await env.DB.prepare(
          'INSERT INTO sync_log (idempotency_key, processed_at) VALUES (?, ?)'
        ).bind(msg.body.idempotencyKey, new Date().toISOString()).run()

        msg.ack()
      } catch (e) {
        msg.retry()  // Queue handles backoff
      }
    }
  },
}
